drop function if exists public.create_source_task(text,uuid,text);
create function public.create_source_task(source_kind text,target_source uuid,task_title text) returns uuid language plpgsql security definer set search_path='' as $$declare station uuid;tid uuid;begin if source_kind='checklist' then select r.station_id into station from public.checklist_run_items i join public.checklist_runs r on r.id=i.run_id where i.id=target_source and i.status='issue';elsif source_kind='issue' then select station_id into station from public.station_issues where id=target_source and deleted_at is null;else raise exception 'Kaynak geçersiz';end if;if station is null or not private.has_permission_in_scope('tasks.create',station) then raise exception 'Görev oluşturma yetkiniz yok';end if;select id into tid from public.tasks where source_type=source_kind and source_id=target_source and deleted_at is null;if tid is not null then return tid;end if;insert into public.tasks(station_id,title,description,priority,status,due_date,evidence_required,evidence_type,review_required,created_by,source_type,source_id)values(station,trim(task_title),'Operasyon kaynağından oluşturuldu',case when source_kind='issue' then 'important' else 'normal' end,'assigned',now()+interval '1 day',false,'none',false,(select auth.uid()),source_kind,target_source)returning id into tid;insert into public.task_assignees(task_id,user_id,assigned_by)values(tid,(select auth.uid()),(select auth.uid()));insert into public.task_events(task_id,actor_id,event_type,metadata)values(tid,(select auth.uid()),'created',jsonb_build_object('source_type',source_kind,'source_id',target_source));perform private.task_notify((select auth.uid()),tid,'task_assigned','Yeni görev oluşturuldu',trim(task_title),'source_task:'||source_kind||':'||target_source);return tid;end$$;
revoke all on function public.create_source_task(text,uuid,text) from public,anon;
grant execute on function public.create_source_task(text,uuid,text) to authenticated;
